package org.viridexa.api.protection;
import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class TurnstileVerifierTest {
 final Instant now=Instant.parse("2026-10-26T00:00:00Z");
 TurnstileProperties properties(){var p=new TurnstileProperties();p.setEnabled(true);p.setMode("test");p.setSiteKey("1x00000000000000000000AA");p.setSecret("1x0000000000000000000000000000000AA");p.setHostnames("example.com");return p;}
 Map<String,Object> valid(){return Map.of("success",true,"hostname","example.com","action","register","challenge_ts",now.toString());}
 @Test void strictSuccessAndReplayAreSingleUse()throws Exception{var t=mock(TurnstileTransport.class);when(t.verify(anyString(),anyString(),anyInt())).thenReturn(valid());var v=new TurnstileVerifier(properties(),t,Clock.fixed(now,ZoneOffset.UTC));v.verify("single-token","register");assertEquals("CHALLENGE_REPLAY",assertThrows(ProtectionException.class,()->v.verify("single-token","register")).code);verify(t,times(1)).verify(anyString(),anyString(),anyInt());}
 @Test void missingOversizedOrInvalidTokensNeverGrantAccess()throws Exception{var t=mock(TurnstileTransport.class);var v=new TurnstileVerifier(properties(),t,Clock.fixed(now,ZoneOffset.UTC));assertEquals("CHALLENGE_REQUIRED",assertThrows(ProtectionException.class,()->v.verify(null,"register")).code);assertThrows(ProtectionException.class,()->v.verify("x".repeat(2049),"register"));verifyNoInteractions(t);when(t.verify(anyString(),anyString(),anyInt())).thenReturn(Map.of("success",false));assertEquals("CHALLENGE_INVALID",assertThrows(ProtectionException.class,()->v.verify("invalid","register")).code);}
 @Test void hostnameAndActionAreRequiredEvenWithProviderSuccess()throws Exception{for(var override:List.of(Map.of("hostname","attacker.invalid"),Map.of("action","login"))){var payload=new HashMap<>(valid());payload.putAll(override);var t=mock(TurnstileTransport.class);when(t.verify(anyString(),anyString(),anyInt())).thenReturn(payload);assertEquals("CHALLENGE_INVALID",assertThrows(ProtectionException.class,()->new TurnstileVerifier(properties(),t,Clock.fixed(now,ZoneOffset.UTC)).verify("token","register")).code);}var payload=new HashMap<>(valid());payload.remove("action");var t=mock(TurnstileTransport.class);when(t.verify(anyString(),anyString(),anyInt())).thenReturn(payload);assertThrows(ProtectionException.class,()->new TurnstileVerifier(properties(),t,Clock.fixed(now,ZoneOffset.UTC)).verify("official-dummy-no-action","register"));}
 @Test void expiredFutureAndMalformedTimestampsFailClosed()throws Exception{for(String ts:List.of(now.minusSeconds(301).toString(),now.plusSeconds(31).toString(),"invalid")){var t=mock(TurnstileTransport.class);var r=new HashMap<>(valid());r.put("challenge_ts",ts);when(t.verify(anyString(),anyString(),anyInt())).thenReturn(r);assertThrows(ProtectionException.class,()->new TurnstileVerifier(properties(),t,Clock.fixed(now,ZoneOffset.UTC)).verify("token","register"));}}
 @Test void providerExpiredResponseHasRecoverableCode()throws Exception{var t=mock(TurnstileTransport.class);when(t.verify(anyString(),anyString(),anyInt())).thenReturn(Map.of("success",false,"error-codes",List.of("timeout-or-duplicate")));assertEquals("CHALLENGE_EXPIRED",assertThrows(ProtectionException.class,()->new TurnstileVerifier(properties(),t).verify("expired","register")).code);}
 @Test void providerUnavailableNeverExposesDiagnosticsOrBypassesCheck()throws Exception{var t=mock(TurnstileTransport.class);when(t.verify(anyString(),anyString(),anyInt())).thenThrow(new java.net.http.HttpTimeoutException("PRIVATE_TOKEN_SECRET"));var e=assertThrows(ProtectionException.class,()->new TurnstileVerifier(properties(),t).verify("private-token","register"));assertEquals(503,e.status);assertFalse(e.toString().contains("PRIVATE"));assertFalse(e.toString().contains("private-token"));}
 @Test void concurrentReplayDoesNotReachProviderTwice()throws Exception{var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var t=mock(TurnstileTransport.class);when(t.verify(anyString(),anyString(),anyInt())).thenAnswer(i->{entered.countDown();assertTrue(release.await(2,TimeUnit.SECONDS));return valid();});var v=new TurnstileVerifier(properties(),t,Clock.fixed(now,ZoneOffset.UTC));try(var executor=Executors.newVirtualThreadPerTaskExecutor()){var first=executor.submit(()->v.verify("same","register"));assertTrue(entered.await(2,TimeUnit.SECONDS));assertEquals("CHALLENGE_REPLAY",assertThrows(ProtectionException.class,()->v.verify("same","register")).code);release.countDown();first.get(2,TimeUnit.SECONDS);}verify(t,times(1)).verify(anyString(),anyString(),anyInt());}
 @Test void productionConfigurationRejectsTestKeysAndIncompleteSecrets(){var p=properties();p.validate();p.setMode("production");assertThrows(IllegalArgumentException.class,p::validate);p.setSiteKey("real-site-key");p.setSecret("real-secret");p.validate();p.setHostnames("localhost");assertThrows(IllegalArgumentException.class,p::validate);}
}
